import sys

import pytest


def test_teardown_request_reverse_order_and_exception(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_exc = ValueError("view failure")
    calls = []

    @app.teardown_request
    def teardown_1(exc):
        calls.append(("teardown_1", exc))

    @app.teardown_request
    def teardown_2(exc):
        calls.append(("teardown_2", exc))

    @app.teardown_request
    def teardown_3(exc):
        calls.append(("teardown_3", exc))

    @app.route("/")
    def index():
        raise view_exc

    response = client.get("/")
    assert response.status_code == 500
    assert calls == [
        ("teardown_3", view_exc),
        ("teardown_2", view_exc),
        ("teardown_1", view_exc),
    ]
    assert all(exc is view_exc for _, exc in calls)


def test_teardown_request_continues_after_error(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_exc = ValueError("view failure")
    teardown_exc = RuntimeError("teardown failure")
    calls = []

    @app.teardown_request
    def teardown_1(exc):
        calls.append(("teardown_1", exc))

    @app.teardown_request
    def teardown_2(exc):
        calls.append(("teardown_2", exc))
        raise teardown_exc

    @app.teardown_request
    def teardown_3(exc):
        calls.append(("teardown_3", exc))

    @app.route("/")
    def index():
        raise view_exc

    if sys.version_info >= (3, 11):
        with pytest.raises(ExceptionGroup, match="Errors during context teardown") as exc_info:  # noqa: F821
            client.get("/")

        assert calls == [
            ("teardown_3", view_exc),
            ("teardown_2", view_exc),
            ("teardown_1", view_exc),
        ]
        assert all(exc is view_exc for _, exc in calls)
        assert len(exc_info.value.exceptions) == 1
        req_eg = exc_info.value.exceptions[0]
        assert isinstance(req_eg, ExceptionGroup)  # noqa: F821
        assert req_eg.message == "Errors during request teardown"
        assert req_eg.exceptions == (teardown_exc,)
    else:
        with pytest.raises(RuntimeError, match="teardown failure") as exc_info:
            client.get("/")

        assert calls == [
            ("teardown_3", view_exc),
            ("teardown_2", view_exc),
            ("teardown_1", view_exc),
        ]
        assert all(exc is view_exc for _, exc in calls)
        assert exc_info.value is teardown_exc

import { Hono } from '../../hono'
import { MESSAGE_MATCHER_IS_ALREADY_BUILT } from '../../router'

describe('SmartRouter with Hono', () => {
  it('uses RegExpRouter when only ordinary routes are registered', async () => {
    const app = new Hono()
    app.get('/', (c) => c.text('root'))
    app.get('/users/:id', (c) => c.text(`user:${c.req.param('id')}`))

    expect(app.router.name).toBe('SmartRouter')

    const rootRes = await app.request('/')
    expect(rootRes.status).toBe(200)
    expect(await rootRes.text()).toBe('root')

    const userRes = await app.request('/users/42')
    expect(userRes.status).toBe(200)
    expect(await userRes.text()).toBe('user:42')

    expect(app.router.name).toBe('SmartRouter + RegExpRouter')
  })

  it('falls back to TrieRouter when a route unsupported by RegExpRouter is registered and answers requests', async () => {
    const app = new Hono()
    app.get('/:user/entries', (c) => c.text(`entries:${c.req.param('user')}`))
    app.get('/entry/:name', (c) => c.text(`entry:${c.req.param('name')}`))
    app.get('/foo/:capture{ba(r|z)}', (c) => c.text(`capture:${c.req.param('capture')}`))

    expect(app.router.name).toBe('SmartRouter')

    const res1 = await app.request('/alice/entries')
    expect(res1.status).toBe(200)
    expect(await res1.text()).toBe('entries:alice')

    expect(app.router.name).toBe('SmartRouter + TrieRouter')

    const res2 = await app.request('/entry/first')
    expect(res2.status).toBe(200)
    expect(await res2.text()).toBe('entry:first')

    const res3 = await app.request('/foo/bar')
    expect(res3.status).toBe(200)
    expect(await res3.text()).toBe('capture:bar')
  })

  it('throws an error when adding a route after the first request has been handled', async () => {
    const app = new Hono()
    app.get('/hello', (c) => c.text('hello'))

    const res = await app.request('/hello')
    expect(res.status).toBe(200)
    expect(await res.text()).toBe('hello')

    expect(() => {
      app.get('/late', (c) => c.text('late'))
    }).toThrow(MESSAGE_MATCHER_IS_ALREADY_BUILT)
  })
})

