Added `test/retry-after-bench.ts` verifying:
1. `Retry-After` given as an HTTP date in the past makes `ky` retry immediately (`source/core/Ky.ts:560-571`).
2. `Retry-After` larger than `retry.maxRetryAfter` is clamped to `maxRetryAfter` (`source/core/Ky.ts:574`).
3. When `Retry-After` is missing, `RateLimit-Reset` is used instead (`source/core/Ky.ts:553-554`).

### Verification

Failing run with the `Retry-After` date parsing, `maxRetryAfter` clamping, and `RateLimit-Reset` fallback removed in `source/core/Ky.ts`:

```
  ✘ [fail]: RateLimit-Reset is used when Retry-After is missing Duration of 936.0413329999999ms is not close to expected duration 2000ms
  ✘ [fail]: Retry-After larger than maxRetryAfter is clamped to maxRetryAfter Duration of 4039.3874160000005ms is not close to expected duration 1680ms
  ✘ [fail]: Retry-After as HTTP date in the past retries immediately Duration of 4542.513792ms is not close to expected duration 16ms
  ─

  3 tests failed
```

Passing run after restoring `source/core/Ky.ts` (`npx ava test/retry-after-bench.ts`):

```
  ✔ Retry-After as HTTP date in the past retries immediately
  ✔ Retry-After larger than maxRetryAfter is clamped to maxRetryAfter (1.7s)
  ✔ RateLimit-Reset is used when Retry-After is missing (2s)
  ─

  3 tests passed
```

### Full Content of `test/retry-after-bench.ts`

```ts
import test from 'ava';
import ky from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';
import {withPerformance} from './helpers/with-performance.js';

const fixture = 'fixture';
const defaultRetryCount = 2;

test('Retry-After as HTTP date in the past retries immediately', async t => {
	const retryCount = 4;
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === retryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(413, {
				'Retry-After': new Date(Date.now() - 10_000).toUTCString(),
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 4 + 4 + 4 + 4,
		async test() {
			t.is(await ky(server.url, {
				retry: retryCount,
			}).text(), fixture);
		},
	});

	t.is(requestCount, 5);
});

test('Retry-After larger than maxRetryAfter is clamped to maxRetryAfter', async t => {
	const retryCount = 4;
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === retryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(413, {
				'Retry-After': 1,
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 420 + 420 + 420 + 420,
		async test() {
			t.is(await ky(server.url, {
				retry: {
					limit: retryCount,
					maxRetryAfter: 420,
				},
			}).text(), fixture);
		},
	});

	t.is(requestCount, 5);
});

test('RateLimit-Reset is used when Retry-After is missing', async t => {
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === defaultRetryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(429, {
				'RateLimit-Reset': 1,
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 1000 + 1000,
		async test() {
			t.is(await ky(server.url).text(), fixture);
		},
	});

	t.is(requestCount, 3);
});
